<script setup lang="ts">
import {computed,ref,reactive,watch,onBeforeUnmount,nextTick} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {useFamilyStore} from '@/stores/family'
import {useSmokingStore} from '@/stores/smoking'
import {createPulseDemo} from '@/visuals/pulseDemo'
import {addLocalDays,getLocalDateString} from '@/utils/date'
import {calculateSmokingStatistics} from '@/utils/statistics'
import {moods,moodLabels,validatePulseDate,type DailyMood} from '@/utils/dailyPulse'
import {planTypes,statusLabels,evaluatePlan,validatePlan,transitionPlan,type Plan,type PlanRole,type PlanType} from '../domain/plans'
import type {CoreState} from '../domain/coreAppearance'
import {submitConstellationCheckin} from '../adapters/checkinBridge'
const emit=defineEmits<{modal:[open:boolean];plan:[nodes:string[],type:PlanType,status:string];feedback:[kind:'record'|'node'|'plan',label:string];cancel:[];state:[value:CoreState|undefined]}>()
const auth=useAuthStore(),family=useFamilyStore(),smoking=useSmokingStore(),today=getLocalDateString()
// Separate in-memory repository: never changes the completed Daily Pulse demo storage.
const memory=new Map<string,string>(),sample=createPulseDemo({getItem:key=>memory.get(key)??null,setItem:(key,value)=>{memory.set(key,value)},removeItem:key=>{memory.delete(key)}},today)
const mode=ref<'mock'|'real'>('mock'),sampleRole=ref<PlanRole>('quitter'),tab=ref<'core'|'plan'>(),pane=ref<'detail'|'edit'>('detail'),busy=ref(false),error=ref(''),success=ref(''),failNext=ref(false),dialog=ref<HTMLElement>()
const role=computed<PlanRole>(()=>mode.value==='mock'?sampleRole.value:family.isQuitter?'quitter':'supporter')
const source=computed(()=>mode.value==='mock'?sample:smoking)
const rows=computed(()=>source.value.checkins)
const date=ref(today),loaded=ref(false),form=reactive({cigarettes:null as number|null,score:null as number|null,mood:null as DailyMood|null,note:''})
const visualState=computed<CoreState|undefined>(()=>{
 if(role.value!=='quitter')return undefined
 if(tab.value==='core'&&loaded.value)return {cigarettes:form.cigarettes,score:form.score,mood:form.mood}
 const row=rows.value.find(value=>value.checkinDate===today)
 return row?{cigarettes:row.cigarettes,score:row.cravingScore??(row.cravingLevel-1)*2.5,mood:row.mood??null}:undefined
})
watch(visualState,value=>emit('state',value),{immediate:true,deep:true})
const plans=ref<Plan[]>([]),focused=ref(''),current=computed(()=>plans.value.find(plan=>plan.id===focused.value))
const evaluation=computed(()=>current.value?evaluatePlan(current.value,rows.value,today):undefined)
const editor=reactive({type:'smokeFree' as PlanType,start:today,end:addLocalDays(today,6),target:7,title:'连续 7 天无烟'})
const drafts=new Map<string,typeof form>();let loadedDate=today
watch(form,()=>{if(loaded.value&&role.value==='quitter')drafts.set(loadedDate,{...form})},{deep:true,flush:'sync'})
let sequence=0,revision=0,previousFocus:HTMLElement|null=null,disposed=false
function syncArc(){emit('plan',evaluation.value?.nodes.map(node=>node.state)??[],current.value?.type??'records',current.value?.status??'empty')}
watch([evaluation,current],syncArc,{immediate:true})
watch(tab,async value=>{emit('modal',Boolean(value));if(value){await nextTick();dialog.value?.querySelector<HTMLElement>('button')?.focus()}else previousFocus?.focus()})
function open(target:'core'|'plan'){previousFocus=document.activeElement as HTMLElement;error.value='';success.value='';tab.value=target;pane.value='detail';if(target==='core'&&role.value==='quitter')void loadDate()}
function close(){if(busy.value)return;tab.value=undefined;revision++}
function message(cause:unknown){error.value=cause instanceof Error?cause.message:'操作失败，请重试'}
async function loadDate(){const token=++revision;loaded.value=false;busy.value=true;error.value='';try{if(role.value!=='quitter')throw new Error('支持者不能打开私人记录');validatePulseDate(date.value,source.value.smokingProfile?.quitStartDate??today,today);const row=await source.value.loadDailyCheckin(date.value);if(token!==revision||disposed)return;Object.assign(form,{cigarettes:row?.cigarettes??null,score:row?.cravingScore??null,mood:row?.mood??null,note:row?.note??''});loadedDate=date.value;if(drafts.has(date.value))Object.assign(form,drafts.get(date.value));loaded.value=true}catch(cause){if(token===revision)message(cause)}finally{if(token===revision)busy.value=false}}
async function changeMode(){if(busy.value)return;busy.value=true;error.value='';const account=auth.user?.id,token=++revision;try{if(mode.value==='mock'){if(!account)throw new Error('真实记录需要登录；当前模拟仍可体验');await family.initializeFamily();if(disposed||token!==revision||account!==auth.user?.id)return;if(!family.isQuitter&&!family.isSupporter)throw new Error('请先完成家庭身份设置');if(family.isQuitter)await smoking.ensureStatisticsLoaded();if(disposed||token!==revision||account!==auth.user?.id)return;mode.value='real'}else mode.value='mock';plans.value=[];focused.value='';drafts.clear();failNext.value=false;success.value='';date.value=today;loaded.value=false}catch(cause){message(cause)}finally{if(token===revision)busy.value=false}if(tab.value==='core'&&!error.value&&role.value==='quitter')await loadDate()}
async function saveCheckin(){if(busy.value||!loaded.value)return;error.value='';success.value='';const token=revision,before=streak();try{if(form.cigarettes===null||form.score===null||form.mood===null)throw new Error('请填写吸烟量、烟瘾与感受');busy.value=true;const result=await submitConstellationCheckin({mode:mode.value,role:()=>role.value,account:()=>mode.value==='real'?auth.user?.id??null:'sample',save:async values=>{if(mode.value==='mock'&&failNext.value){failNext.value=false;throw new Error('模拟保存失败；输入已保留')}return source.value.saveDailyCheckin(values)}},{checkinDate:date.value,cigarettes:form.cigarettes,cravingLevel:1+Math.round(form.score*4/10),cravingScore:form.score,mood:form.mood,note:form.note});if(disposed||token!==revision)return;drafts.delete(date.value);success.value=result.source==='mock'?'已保存 · 本页模拟':'已保存';const after=streak();emit('feedback',date.value===today&&[1,3,7,14,30,100].includes(after)&&after>before?'node':'record',success.value);reverifyPlans()}catch(cause){if(!disposed&&token===revision)message(cause)}finally{if(token===revision)busy.value=false}}
function streak(){const profile=source.value.smokingProfile;return profile?calculateSmokingStatistics(profile,rows.value,today).currentStreak:0}
function reverifyPlans(){plans.value=plans.value.map(plan=>['active','completed','missed'].includes(plan.status)&&role.value==='quitter'?transitionPlan(plan,'verify',role.value,rows.value,today):plan)}
function editPlan(){error.value='';if(current.value)Object.assign(editor,{type:current.value.type,start:current.value.start,end:current.value.end,target:current.value.target,title:current.value.title});pane.value='edit'}
function newPlan(){focused.value='';Object.assign(editor,{type:'smokeFree',start:today,end:addLocalDays(today,6),target:7,title:'连续 7 天无烟'});pane.value='edit';error.value=''}
function savePlan(){error.value='';try{validatePlan(editor);if(failNext.value){failNext.value=false;throw new Error('模拟计划保存失败；输入已保留')}const old=current.value;if(old&&(role.value!=='quitter'||['completed','cancelled','expired'].includes(old.status)))throw new Error('当前计划不能修改');const value:Plan={...editor,title:editor.title.trim(),id:old?.id??`plan-${++sequence}`,version:(old?.version??0)+1,proposer:role.value,status:'proposed',participants:[role.value],confirmedDates:[],reason:old?'目标已修改，需重新接受':'',source:'mock'};plans.value=plans.value.filter(plan=>plan.id!==value.id).concat(value);focused.value=value.id;pane.value='detail';success.value='提案已保存 · 本页模拟'}catch(cause){message(cause)}}
function action(kind:Parameters<typeof transitionPlan>[1]){if(!current.value)return;error.value='';try{if(failNext.value){failNext.value=false;throw new Error('模拟状态更新失败')}const old=current.value,next=transitionPlan(old,kind,role.value,rows.value,today);plans.value=plans.value.map(plan=>plan.id===next.id?next:plan);if(old.status!=='completed'&&next.status==='completed')emit('feedback','plan','计划达成 · 模拟纪念');success.value=statusLabels[next.status]}catch(cause){message(cause)}}
function join(){if(current.value&&!current.value.participants.includes(role.value))plans.value=plans.value.map(plan=>plan.id===focused.value?{...plan,participants:[...plan.participants,role.value]}:plan)}
function keyboard(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();close()}if(event.key==='Tab'){const nodes=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
watch(()=>auth.user?.id,()=>{revision++;busy.value=false;loaded.value=false;plans.value=[];focused.value='';tab.value=undefined;mode.value='mock';drafts.clear();error.value='';Object.assign(form,{cigarettes:null,score:null,mood:null,note:''})})
watch(sampleRole,()=>{success.value='';error.value='';loaded.value=false;if(tab.value==='core'&&role.value==='quitter')void loadDate()})
onBeforeUnmount(()=>{disposed=true;revision++;memory.clear()})
defineExpose({open,setSampleRole:(value:PlanRole)=>{sampleRole.value=value}})
</script>
<template>
 <div v-if="tab" class="workbench-backdrop" @click.self="close"><section ref="dialog" class="workbench" role="dialog" aria-modal="true" :aria-label="tab==='core'?'核心打卡':'共同计划'" @keydown="keyboard">
  <header><span>{{tab==='core'?'今日光核':'共同计划'}}</span><button :disabled="busy" aria-label="关闭联动浮层" @click="close">×</button></header>
  <div class="source-line"><span>{{mode==='mock'?'本页模拟':'本人真实记录'}}{{tab==='plan'?' · 计划不联网':''}}</span><button :disabled="busy" @click="changeMode">{{mode==='mock'?'读取本人记录':'切回模拟'}}</button></div>
  <label v-if="mode==='mock'" class="role-select">体验身份<select v-model="sampleRole" :disabled="busy" aria-label="模拟身份"><option value="quitter">戒烟者</option><option value="supporter">支持者</option></select></label>
  <template v-if="tab==='core'">
   <label class="date-label">日期<input v-model="date" type="date" :min="source.smokingProfile?.quitStartDate??today" :max="today" :disabled="busy" @change="loadDate"/></label>
   <p v-if="role==='supporter'" class="permission">支持者只读；不开放私人备注，不可代打卡。</p>
   <form v-if="loaded&&role==='quitter'" @submit.prevent="saveCheckin"><fieldset :disabled="busy">
    <label class="amount-label">吸烟量 <small>支</small><div class="number-input"><button type="button" aria-label="减少一支" @click="form.cigarettes=Math.max(0,(form.cigarettes??0)-1)">−</button><input v-model.number="form.cigarettes" aria-label="吸烟量" type="number" min="0" max="200" required/><button type="button" aria-label="增加一支" @click="form.cigarettes=Math.min(200,(form.cigarettes??0)+1)">＋</button></div></label>
    <label>烟瘾 {{form.score??'—'}} / 10<input :value="form.score??0" type="range" min="0" max="10" step="1" aria-label="烟瘾" @input="form.score=Number(($event.target as HTMLInputElement).value)"/></label><button v-if="form.score===null" type="button" class="small-action" @click="form.score=0">选择 0 · 平稳</button>
    <div class="moods" role="group" aria-label="每日感受"><button v-for="mood in moods" :key="mood" type="button" :aria-pressed="form.mood===mood" @click="form.mood=mood">{{moodLabels[mood]}}</button></div>
    <details><summary>备注 +</summary><textarea v-model="form.note" aria-label="私人备注" maxlength="160" rows="2"/></details>
    <button class="primary" type="submit">{{busy?'保存中…':date===today?'保存打卡':'保存补录'}}</button>
   </fieldset></form>
   <button v-if="!loaded&&!busy" @click="loadDate">重新读取</button>
  </template>
  <template v-else>
   <nav class="plan-list" aria-label="本页计划"><button v-for="plan in plans" :key="plan.id" :aria-pressed="focused===plan.id" @click="focused=plan.id;pane='detail';error='';success=''">{{plan.title}}</button><button aria-label="新建计划" @click="newPlan">＋</button></nav>
   <form v-if="pane==='edit'" @submit.prevent="savePlan"><label>类型<select v-model="editor.type" aria-label="计划类型"><option v-for="(name,key) in planTypes" :key="key" :value="key">{{name}}</option></select></label><label>目标名称<input v-model="editor.title" maxlength="40" required aria-label="目标名称"/></label><div class="date-pair"><label>起始<input v-model="editor.start" type="date" required aria-label="计划起始"/></label><label>截止<input v-model="editor.end" type="date" required aria-label="计划截止"/></label></div><label>{{editor.type==='limit'?'累计支数上限':'目标天数'}}<input v-model.number="editor.target" type="number" min="1" required aria-label="计划目标"/></label><button class="primary" type="submit">保存提案 · 模拟</button></form>
   <section v-else-if="current" class="plan-detail" :data-plan-status="current.status"><h2>{{current.title}}</h2><span>{{statusLabels[current.status]}} · v{{current.version}}</span><p>{{current.start}} — {{current.end}}</p><div class="plan-nodes"><i v-for="node in evaluation?.nodes" :key="node.date" :class="node.state" :title="`${node.date} · ${node.state}`"/></div><p>{{current.type==='limit'?`${evaluation?.coverage}/${evaluation?.days} 日覆盖 · ${evaluation?.total} / ${current.target} 支`:`${evaluation?.progress} / ${current.target} 天`}}</p><small>{{current.type==='scene'?'自主确认，打卡无法验证吸烟时刻':current.type==='limit'?'必须完整日期覆盖后核验累计支数':current.type==='records'?'有烟记录也计入；缺失日不通过':'仅逐日零支通过，缺失日不通过'}}</small><p v-if="current.reason">{{current.reason}}</p>
    <div class="plan-actions"><template v-if="role==='quitter'"><button v-if="current.status==='proposed'" @click="action('accept')">接受</button><button v-if="current.status==='accepted'" @click="action('activate')">激活</button><button v-if="['active','completed','missed'].includes(current.status)" @click="action('verify')">重新核验</button><button v-if="current.type==='scene'&&current.status==='active'" @click="action('confirm')">自主确认今天</button><button v-if="!['completed','cancelled','expired'].includes(current.status)" @click="editPlan">修改</button><button v-if="!['completed','cancelled','expired'].includes(current.status)" @click="action('cancel')">取消计划</button></template><button v-else @click="join">加入陪伴 · 模拟</button><button v-if="current.status==='proposed'&&today>current.end" @click="action('expire')">标记过期</button></div>
   </section><button v-else class="primary" @click="newPlan">创建一个计划</button>
  </template>
  <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" class="success" role="status">{{success}} <button class="small-action" @click="emit('cancel')">跳过光效</button></p><button v-if="mode==='mock'" class="fault" @click="failNext=true">模拟下次保存失败</button>
 </section></div>
</template>
<style scoped>
.workbench-backdrop{position:fixed;inset:0;z-index:12;display:flex;align-items:center;justify-content:flex-end;padding:28px 5%;background:#10162235}.workbench{width:370px;max-height:85svh;overflow:auto;padding:24px;box-sizing:border-box;color:#e8e5df;background:linear-gradient(145deg,#333b47ed,#202830f5);border:1px solid #b3bbbc38;border-radius:22px;box-shadow:0 20px 75px #0005;font:12px Inter,'Microsoft YaHei',sans-serif}.workbench header{display:flex;align-items:center;justify-content:space-between;font-size:16px}.workbench button{min-height:40px;min-width:40px;cursor:pointer;border:1px solid #b6bec32a;border-radius:12px;background:#b8c6cd08;color:inherit;font:inherit;padding:8px 12px}.workbench header button{border:0;font-size:22px}.source-line{display:flex;align-items:center;justify-content:space-between;color:#bac2c5;font-size:10px;margin:10px 0 18px}.source-line button{font-size:10px}.workbench label{display:block;margin:12px 0;color:#cdd1d1}.workbench input,.workbench select,.workbench textarea{box-sizing:border-box;display:block;max-width:100%;width:100%;background:#181f2b66;border:1px solid #a4b3b32c;border-radius:9px;color:#ece8df;padding:10px;margin-top:8px;font:inherit;color-scheme:dark}.workbench select{background:#28313c}.workbench input[type=range]{padding:0;accent-color:#c5aa75}.role-select{display:flex!important;align-items:center;justify-content:space-between}.role-select select{width:110px;margin:0}.number-input{display:flex;align-items:center;justify-content:center;gap:18px}.number-input input{font-size:40px;text-align:center;width:110px;background:none;border:0}.amount-label small{color:#9eaeb6}.moods{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:18px 0}.moods button[aria-pressed=true],.plan-list button[aria-pressed=true]{background:#c6ac7330;border-color:#c6ac7388}.workbench fieldset{border:0;padding:0;margin:0}.workbench summary{cursor:pointer;color:#a7b5ba;margin:18px 0}.workbench .primary{display:block;width:100%;margin-top:20px;background:#cfb782e0;color:#202831;border:0}.workbench .fault{display:block;margin-top:18px;border:0;opacity:.6;font-size:9px}.workbench .error{color:#f4b9a0;line-height:1.7}.workbench .success{color:#d3daba}.permission{color:#c9c9bc;line-height:1.8}.date-pair{display:flex;gap:10px}.date-pair label{min-width:0;flex:1}.plan-list{display:flex;gap:7px;overflow:auto;padding-bottom:8px}.plan-list button{white-space:nowrap;font-size:11px}.plan-detail h2{font-size:18px;font-weight:400;margin:20px 0 10px}.plan-detail>span,.plan-detail small{color:#b9c3c6;font-size:10px;line-height:1.8}.plan-detail p{font-size:11px;color:#c9ced0}.plan-nodes{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}.plan-nodes i{width:8px;height:8px;border:1px solid #a0b1c144;border-radius:50%}.plan-nodes .verified{background:#e8cd95;box-shadow:0 0 10px #d9b57955}.plan-nodes .unmet{background:#7f929c}.plan-nodes .missing{border-style:dashed}.plan-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:20px}.workbench :focus-visible{outline:2px solid #d9bd86;outline-offset:3px}.workbench button:disabled{opacity:.4;cursor:wait}@media(max-width:700px){.workbench-backdrop{padding:12px;align-items:flex-end}.workbench{width:100%;max-height:88svh;padding:20px}}
</style>
